#!/usr/bin/env bash
# Generated by Dagly, profile helio_catalog_artifact_v1, from GoCD deploy pipelines ReportingAPIIntNA, ReportingProcessorIntNA (template DockerAppDeployTemplate).
# Runs the deploy tasks for one catalog environment against the artifact the
# platform resolved, then independently reads every intended target. Success
# is reported only when all of them run exactly that digest.
set -euo pipefail
: "${RESULT_FILE:?}" "${ARTIFACT_URI:?}" "${ARTIFACT_DIGEST:?}" "${BUILD_VERSION:?}" "${TARGET_ENVIRONMENT:?}" "${OPERATION_ID:?}"
[[ "$TARGET_ENVIRONMENT" =~ ^[a-z0-9][a-z0-9._-]{0,62}$ ]]
[[ "$ARTIFACT_DIGEST" =~ ^sha256:[a-f0-9]{64}$ ]]
[[ "$ARTIFACT_URI" == 'localhost:3546/bm-sellside-reporting-fe-20261028'"@${ARTIFACT_DIGEST}" ]] || { echo 'artifact is not from this application image' >&2; exit 1; }
WORK="$(mktemp -d "${RUNNER_TEMP:-/tmp}/gocd-deploy.XXXXXX")"
DOCKER_CONFIG="$(mktemp -d)"; export DOCKER_CONFIG
trap 'rm -rf -- "$WORK" "$DOCKER_CONFIG"' EXIT
read_secret() {
  python3 -c 'import json,os,sys; v=json.loads(os.environ.get("HELIO_SECRETS_JSON") or "{}").get(sys.argv[1]); sys.exit("missing secret " + sys.argv[1]) if v is None else print(v, end="")' "$1"
}
# GoCD built-in variables; GO_PIPELINE_LABEL is the build's version. The
# environment's own GO_PIPELINE_NAME comes from its settings below.
export GO_PIPELINE_NAME='ReportingAPIIntNA'
export GO_PIPELINE_COUNTER="$GITHUB_RUN_NUMBER"
export GO_STAGE_NAME='Deploy'
export GO_STAGE_COUNTER="$GITHUB_RUN_ATTEMPT"
export GO_JOB_NAME='deploy'
export GO_REVISION="$GITHUB_SHA"
export GO_TRIGGER_USER="$GITHUB_ACTOR"
export GO_SERVER_URL="${GITHUB_SERVER_URL:-https://github.com}"
export GO_PIPELINE_LABEL="$BUILD_VERSION"
# This environment's deployment settings: the snapshot the runtime froze with
# the run's plan (HELIO_TARGET_SETTINGS), read by declared name only. Nothing
# else in it can reach the environment, and control names are refused upstream.
: "${HELIO_TARGET_SETTINGS:?no frozen deployment settings for this environment}"
read_setting() {
  python3 -c 'import json,os,sys; v=json.loads(os.environ["HELIO_TARGET_SETTINGS"]).get(sys.argv[1]); sys.exit("setting " + sys.argv[1] + " is missing") if v is None else print(v, end="")' "$1"
}
AWS_PROFILE="$(read_setting 'AWS_PROFILE')"; export AWS_PROFILE
DEPLOY_DC="$(read_setting 'DEPLOY_DC')"; export DEPLOY_DC
DEPLOY_ENV="$(read_setting 'DEPLOY_ENV')"; export DEPLOY_ENV
DEPLOY_REGION="$(read_setting 'DEPLOY_REGION')"; export DEPLOY_REGION
GO_PIPELINE_NAME="$(read_setting 'GO_PIPELINE_NAME')"; export GO_PIPELINE_NAME
INVENTORY_GROUP="$(read_setting 'INVENTORY_GROUP')"; export INVENTORY_GROUP
INVENTORY_SCRIPT="$(read_setting 'INVENTORY_SCRIPT')"; export INVENTORY_SCRIPT
PLAYBOOK="$(read_setting 'PLAYBOOK')"; export PLAYBOOK
EXPECTED_TARGETS="$(read_setting expected_targets)"
[[ "$EXPECTED_TARGETS" =~ ^[1-9][0-9]{0,3}$ ]] || { echo 'expected_targets must be a positive integer' >&2; exit 1; }
# Secrets of the deploy pipelines: the destination-to-secret map every
# deploy pipeline shares, so every environment gets the same names
# GoCD materials at their locked revisions
rev="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["materials"][sys.argv[2]]["revision"])' "$GITHUB_WORKSPACE/cicd/helio-materials.lock.json" 'ansible')"
[[ "$rev" =~ ^[a-f0-9]{40}$ ]] || { echo 'material ansible is not locked to a commit' >&2; exit 1; }
git init -q "$WORK"/'ansible'
git -C "$WORK"/'ansible' fetch -q --depth 1 'https://github.com/helloangular/bm-sellside-ansible-20261028.git' "$rev"
git -C "$WORK"/'ansible' checkout -q FETCH_HEAD
export GO_REVISION_ANSIBLE="$rev" GO_MATERIAL_BRANCH_ANSIBLE='master' GO_MATERIAL_URL_ANSIBLE='https://github.com/helloangular/bm-sellside-ansible-20261028.git'
# The GoCD tasks, in order, under their run_if conditions; the fetch of
# buildVersion.sh is recreated from the artifact envelope
gocd_failed=0
# task 0
if [ "$gocd_failed" = 0 ]; then ( mkdir -p "$WORK"; printf 'BUILD_VERSION=%s\nREVISION_SOURCE=%s\n' "$BUILD_VERSION" "$GITHUB_SHA" > "$WORK"/'buildVersion.sh'; ) || gocd_failed=1; fi
# task 1
if [ "$gocd_failed" = 0 ]; then ( cd "$WORK"/'ansible' && 'echo' 'Environment dump removed by reviewed security mapping' ) || gocd_failed=1; fi
# task 2 (playbook given the artifact digest)
if [ "$gocd_failed" = 0 ]; then ( cd "$WORK"/'ansible' && '/bin/bash' '-c' 'chmod 775 ../buildVersion.sh; source ../buildVersion.sh; /usr/local/ansible/bin/ansible-playbook --extra-vars "helio_artifact_uri=${ARTIFACT_URI} helio_artifact_digest=${ARTIFACT_DIGEST}" ./playbooks/slack_announce_release.yml -i ${INVENTORY_SCRIPT} -u deploy --extra-vars "app_inventory_group_name=${INVENTORY_GROUP} app_version=${BUILD_VERSION} release_status=Starting slack_color=warning"' ) || gocd_failed=1; fi
# task 3 (playbook given the artifact digest)
if [ "$gocd_failed" = 0 ]; then ( cd "$WORK"/'ansible' && '/bin/bash' '-c' 'chmod 775 ../buildVersion.sh; source ../buildVersion.sh; /usr/local/ansible/bin/ansible-playbook --extra-vars "helio_artifact_uri=${ARTIFACT_URI} helio_artifact_digest=${ARTIFACT_DIGEST}" ${PLAYBOOK} -i ${INVENTORY_SCRIPT} -u deploy --extra-vars "app_inventory_group=${INVENTORY_GROUP} app_version=${BUILD_VERSION} deploy_env=${DEPLOY_ENV} deploy_version=${GO_PIPELINE_LABEL} local_working_dir=`pwd`" --limit="localhost,haproxy,${INVENTORY_GROUP}"' ) || gocd_failed=1; fi
# task 4 (playbook given the artifact digest)
if [ "$gocd_failed" = 0 ]; then ( cd "$WORK"/'ansible' && '/bin/bash' '-c' 'chmod 775 ../buildVersion.sh; source ../buildVersion.sh; /usr/local/ansible/bin/ansible-playbook --extra-vars "helio_artifact_uri=${ARTIFACT_URI} helio_artifact_digest=${ARTIFACT_DIGEST}" ./playbooks/slack_announce_release.yml -i ${INVENTORY_SCRIPT} -u deploy --extra-vars "app_inventory_group_name=${INVENTORY_GROUP} app_version=${BUILD_VERSION} release_status=Completed slack_color=good"' ) || gocd_failed=1; fi
# task 5 (playbook given the artifact digest)
if [ "$gocd_failed" = 1 ]; then ( cd "$WORK"/'ansible' && '/bin/bash' '-c' 'chmod 775 ../buildVersion.sh; source ../buildVersion.sh; /usr/local/ansible/bin/ansible-playbook --extra-vars "helio_artifact_uri=${ARTIFACT_URI} helio_artifact_digest=${ARTIFACT_DIGEST}" ./playbooks/slack_announce_release.yml -i ${INVENTORY_SCRIPT} -u deploy --extra-vars "app_inventory_group_name=${INVENTORY_GROUP} app_version=${BUILD_VERSION} release_status=Failed slack_color=danger"' ) || true; fi
[ "$gocd_failed" = 0 ] || { echo 'GoCD deploy task failed; the target is not verified' >&2; exit 1; }
# Independent verification: one observed digest per intended target. The
# verifier must succeed; output from a failing verifier is never accepted.
if ! observed="$(cd "$WORK" && c="bm-sellside-reporting-fe-$TARGET_ENVIRONMENT"; [ "$(docker inspect -f '{{.State.Running}}' "$c")" = true ] || exit 1; docker image inspect -f '{{range .RepoDigests}}{{println .}}{{end}}' "$(docker inspect -f '{{.Image}}' "$c")" | sed -n 's#^localhost:3546/bm-sellside-reporting-fe-20261028@##p')"; then
  echo 'target verification command failed; no receipt is written' >&2
  exit 1
fi
OBSERVED="$observed" python3 - "$RESULT_FILE" "$EXPECTED_TARGETS" <<'PY'
import json, os, sys
lines = [l.strip() for l in os.environ['OBSERVED'].splitlines() if l.strip()]
want = os.environ['ARTIFACT_DIGEST']
if len(lines) != int(sys.argv[2]): raise SystemExit('observed %d targets, expected %s' % (len(lines), sys.argv[2]))
wrong = [l for l in lines if l != want]
if wrong: raise SystemExit('a target runs ' + wrong[0] + ', not ' + want)
json.dump({'operation_id': os.environ['OPERATION_ID'], 'environment': os.environ['TARGET_ENVIRONMENT'],
           'observed_artifact_digest': want}, open(sys.argv[1], 'w'))
PY
